using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int Charged(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeCustomerIsChargedTheBronzePrice() =>
        Assert.Equal(9500, Charged(10000, LoyaltyTier.Bronze));

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverCustomerIsChargedTheSilverPrice() =>
        Assert.Equal(9000, Charged(10000, LoyaltyTier.Silver));

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldCustomerIsChargedTheGoldPrice() =>
        Assert.Equal(8500, Charged(10000, LoyaltyTier.Gold));

    // Bronze customer with a tiny basket is charged a whole cent in their favour
    [Fact]
    public void S4_BronzeTinyBasketIsChargedAWholeCentInTheirFavour() =>
        Assert.Equal(7, Charged(7, LoyaltyTier.Bronze));
}
E
